import { useState } from "react";
//#region src/useCycleList/index.ts
const useCycleList = (list, i = 0) => {
	const [index, setIndex] = useState(i);
	const set = (i) => {
		const length = list.length;
		const nextIndex = ((index + i) % length + length) % length;
		setIndex(nextIndex);
	};
	const next = (i = 1) => {
		set(i);
	};
	const prev = (i = 1) => {
		set(-i);
	};
	return [
		list[index],
		next,
		prev
	];
};
//#endregion
export { useCycleList };
